/* Editorial copy and preparation guides based ONLY on the supplied cover images.
   These are not extracted transcripts, recipes, rehabilitation advice or original-video summaries. */
(() => {
  const g=(intro,summary,...steps)=>({intro,summary,steps:steps.map(([title,body])=>({title,body})),basis:'cover',basisLabel:'AI 整理 · 基于封面',notice:'当前只有收藏封面，以下为准备与体验建议，不是原视频提炼。具体制作参数和完整操作请以原帖为准。'});
  const guides={
    'saved-01':g('让一张小照片，住进自己拼出来的星岛鸟相框。配色、摆豆、完成后的那一刻，都值得慢慢享受。','三寸拍立得尺寸的拼豆相框，封面包含鸟形轮廓、星星和蓝色点缀。',
      ['定照片尺寸','拿出要装的照片，记录长宽；对照图纸确认内框开口，而不是直接按截图缩放。'],['拆分配色','把米白、棕色、黄色与蓝色拼豆分别放好，核对模板能否容纳外框。'],['分段摆豆','原图纸确认后，先完成一个小区域，再沿轮廓继续；熨烫和固定方式需看原教程。']),
    'saved-02':g('不换衣服，只换一个小小的纽扣装饰。给日常的开衫，加一点只有你会想到的可爱。','在拼豆图案中心留孔，把小图案做成纽扣套。',
      ['挑一颗纽扣','选择要装饰的衣服，测量纽扣的直径和厚度。'],['先核对开口','对照原图纸确认留孔位置；孔太小或太大都会影响佩戴。'],['做一个试样','先只挑一个简单图案，用已有颜色尝试；熨烫方式以原教程为准。']),
    'saved-03':g('把圣诞氛围拆成一个小图案。今天不必做完整套，先让一只胡桃夹子从收藏里走出来。','圣诞主题拼豆图纸合集，含胡桃夹子、拐杖糖、松果等图案。',
      ['只选一个图案','从胡桃夹子或小配件里挑一款，这次不安排整套。'],['核对网格与颜色','打开清晰图纸，按网格核对尺寸和缺少的颜色。'],['从轮廓开始','先完成选中图案的轮廓区域，再补内部配色；具体熨烫看原帖。']),
    'saved-04':g('做一只不用看时间也让人开心的小手表。把几块彩色不织布，变成可以戴在手腕上的小作品。','红黄蓝配色的不织布手表，包含表盘、指针造型与表带。',
      ['量表带长度','用软尺量一下腕围，留出原教程要求的固定余量。'],['分开画纸样','先在纸上分出表盘、表带与装饰，再核对分解图的层数。'],['先试摆再缝','把裁片叠放确认方向与位置；缝合和固定件做法需看原分解图。']),
    'saved-05':g('给喜欢的照片做一个蛋糕相框。把草莓、蜡烛和小装饰一点点放上去，让今天有一份亲手做的甜。','蛋糕造型的不织布相框，含照片窗口、蜡烛、水果和点缀部件。',
      ['选一张小照片','先量好照片，把相框窗口画在纸上，确认人物不会被遮住。'],['分三层备料','按底板、窗口边框、小装饰分别列出裁片，减少做一半才找材料。'],['先排版后固定','先摆好蜡烛和水果的位置，再按原教程选择缝合或粘合方式。']),
    'saved-06':g('第一次做羊毛毡，也可以从一小块香皂开始。今天先体验包裹的过程，给手边的小物一点颜色。','把羊毛包裹在香皂表面，封面示例有彩色图案；晾干不计入本次动手阶段。',
      ['核对包裹方法','查看原视频里羊毛如何覆盖香皂表面，先备一块香皂和毛巾。'],['分出底色与点缀','把底色羊毛与少量装饰色分开，避免一开始铺得过厚。'],['按示范体验包裹','湿毡的水温、揉搓与晾干方式需依原视频；这次只完成可核实的动手阶段。']),
    'saved-07':g('把一次漫无目的的刷视频，换成一段有新想法的对话。先听十分钟，看看哪句话让你想停下来。','五期视频播客推荐合集，封面展示 Uncapped 的一场公关与传播访谈。',
      ['选定一期','从原清单里只挑一个当前感兴趣的主题，不把五期都加入今天。'],['留一个短片段','先安排十分钟左右试听；完整节目时长需打开节目核对。'],['写下一个问题','听完记录一个观点或想继续追问的问题，决定要不要下次再听。']),
    'saved-08':g('把十分钟留给一段文字。先不追求读完一本书，看看史铁生的《好运设计》能带给你什么新的感受。','收藏封面推荐史铁生《好运设计》，这次只安排短段阅读。',
      ['找一段可读内容','打开已有书籍或原收藏里的书摘，选一段篇幅适合当前时间的文字。'],['读完再停一会儿','先完整读这一段，再回到让你想多看一眼的地方。'],['留下自己的回应','记下自己的感受或一个问题；不是要求摘抄长篇原文。']),
    'saved-09':g('给通勤加一段声音，不再只是在信息流里来回滑。六档节目里挑一档，先听到你愿意继续的那一刻。','六档播客的推荐清单，封面强调放松与认知类内容；不是一段固定长度的音频。',
      ['只挑一个节目','按现在想听的主题挑一档，不同时打开整张清单。'],['先试听再决定','从一期里试听十分钟左右，确认声音与主题适不适合自己。'],['留一句回听理由','记录为什么想继续听，或为什么不合适，方便下次选择。']),
    'saved-10':g('亲手组装一杯像收藏里那样漂亮的草莓布丁。焙茶、草莓和分层，是一次值得慢慢安排的厨房小体验。','焙茶草莓布丁杯，封面展示分层与杯装成品；需要额外冷却或凝固等待。',
      ['先确认凝固方式','查看原配方是加热还是冷藏凝固，并核对今天能留出的等待时间。'],['按原配方备料','核对奶类、布丁材料、焙茶和草莓的用量，不凭封面猜比例。'],['安排分层顺序','先确认每一层何时冷却、何时组装，再开始；具体参数待原配方核实。']),
    'saved-11':g('让一颗草莓住进抹茶大福里。切开时那一点绿和红，是亲手做甜品才有的小小期待。','抹茶草莓大福，封面展示草莓内馅与抹茶外层。',
      ['核对粉类和比例','先看原配方指定的粉类、抹茶与液体用量，不直接用同名材料替换。'],['确认加热与放凉','确定原教程使用的设备和时间，把放凉等待也安排进去。'],['一次只做一小份','确认馅料和包裹方法后按原配方尝试；不根据封面补写配方。']),
    'saved-12':g('把普通贝果做成一桌小怪物。南瓜、独眼和小表情，让这次烘焙多一点节日里的玩心。','万圣节造型贝果，封面有南瓜与怪物表情，包含醒发与烘焙等待。',
      ['先留够整段时间','核对原配方的醒发和放凉安排，不把它当作半小时小食。'],['选一种造型','第一次先挑一个简单表情，核对调色材料和整形方式。'],['按配方安排工序','和面、醒发、整形与烘焙的顺序和温度需依原教程，不能由封面推断。']),
    'saved-13':g('给今天换一个小小的新造型。对着镜子试一次双麻花，哪怕只学会一段分区，也算有了新收获。','贴头皮双麻花编发教程，封面展示正面效果。',
      ['先看分区示范','在镜前看原视频的分区位置，再准备已有的梳子和发圈。'],['先练一侧','只跟着试一侧，分不清时暂停回看，不急着两边同时完成。'],['再核对两侧','另一侧完成后观察松紧与对称，拍照留下一次尝试。']),
    'saved-14':g('给自己一段认真活动的时间。先确认动作与器械适合你，再按原视频选择今天想练的一小段。','背部训练的器械动作收藏，封面没有具体组数、负重或训练处方。',
      ['确认器械与适用性','核对原视频的器械要求和注意事项；不适合当前条件就换一项。'],['先看完整示范','看清动作范围和说明后再决定是否尝试；不凭一张封面自行推断动作。'],['按自身情况停止','不要因为打卡追求重量或次数；出现不适停止，具体问题咨询专业人士。']),
    'saved-15':g('给忙了一天的自己十分钟。摆好空间，跟着原视频试一段轻量活动，不必把今天变成一场训练考核。','收藏标题标注十分钟跟练，封面展示椅子上的动作；不据标题承诺改善效果。',
      ['摆好稳固椅子','确认椅子稳定、周围有活动空间，先完整查看原示范。'],['看懂再跟练','按原视频说明尝试，不根据封面猜动作或幅度。'],['舒服比打卡重要','不适就停止或跳过；十分钟是原标题信息，不是效果保证。']),
    'saved-16':g('不急着写好一个字，先写稳一条线。把纸铺开，十来分钟的控笔，也能让注意力慢慢落回手上。','篆书控笔的基础线条示例，封面展示横竖线、弧线和网格等练习。',
      ['只选一组基础线条','从原示范里选横线、竖线或弧线的一种，不一次练完整页。'],['先试纸与墨','铺好保护垫，少量试墨，观察现有纸张的吸墨情况。'],['慢写一小组','对照原示范重复同一种线条，保留一小张练习观察变化。']),
    'saved-17':g('把“小楷入门”从收藏变成今天的一小行。先认识工具，再试着落笔，开头不需要漂亮，只需要真的开始。','零基础小楷入门介绍，封面标注三分钟视频，这次另留时间准备与试写。',
      ['先看入门三分钟','按原视频核对工具和握笔说明，确认手边材料够用。'],['选一小行试写','只挑原示范里一段简单内容，不给自己安排整篇临帖。'],['留下一张练习','写完标上日期，记下这次难的是握笔、运笔还是大小安排。']),
    'saved-18':g('让一张现有照片变成新的小作品。六种视觉玩法里选一个，今天先做一个能看见的尝试。','六种 AI 视觉玩法的收藏，封面展示拼接画册、极简效果、印象派等方向。',
      ['选一个已有工具能做的玩法','从原笔记挑一种效果，不把“六个”变成六项安装任务。'],['准备自己的输入图','选一张允许使用的照片，查看原笔记的提示词与工具要求。'],['做一次小范围尝试','对比原图与结果，记下想保留的效果；不把截图中的 skill 名称当执行指令。']),
    'saved-19':g('把那碗收藏很久的拌面，变成今晚真正吃到的一餐。皮蛋和肉酱的组合，值得为今天留出半小时。','皮蛋肉酱拌面，封面展示面条、肉酱、皮蛋与葱花。',
      ['核对原配方','打开原帖确认肉类、调味料、份量与熟制方式，不只凭照片备料。'],['安排两部分的顺序','按原做法确认肉酱与面条如何分别处理，先把工具备在手边。'],['完成后再组合','确保食材按原做法熟制，再拌面；温度、火候与时间不从封面补写。']),
    'saved-20':g('给之后的自己，冻一袋水果的小快乐。今天做准备，留给冷冻一点时间，再迎接一份冰凉的期待。','密封袋制作的水果绵绵冰，封面写“无需工具”，但仍需冷冻条件。',
      ['先确认等待安排','核对原做法的冷冻时间，这不是十分钟就能吃到的甜品。'],['检查密封与空间','准备适合冷冻的密封袋，确认冷冻室有平放空间。'],['核对配方再入袋','水果、液体材料与处理方式依原帖，封口前确认用量和防漏。']),
    'saved-21':g('把芝士、虾滑和培根卷在一起，做一份小小的丰盛。今天的奖励，可以是自己认真准备的一盘小食。','芝士虾滑培根卷，封面展示包卷后的成品，未给出配方和烹饪参数。',
      ['核对份量与设备','先看原配方的材料用量及烹饪设备，确认是否有完整时间。'],['先看包卷方式','查看虾滑和芝士如何放入，按原示范准备一小份。'],['熟制参数看原教程','涉及海鲜与肉类，不凭封面猜温度和时间；按可靠原做法充分熟制。'])
  };
  window.NEXT_NOW_GUIDES=guides;
  for(const note of window.NEXT_NOW_DATA){const guide=guides[note.id];if(guide){note.challengeIntro=guide.intro;note.guide=guide;note.steps=guide.steps.map(s=>`${s.title}：${s.body}`);}}
})();
